+          convo = [{ role: 'user', content: `${task.prompt}\n\n<digest-so-far>\n${digestText}\n</digest-so-far>` }, ...convo.slice(convo.length - 2)];
+          onEvent({ type: 'reviewer', text: '(curated the conversation into a digest)', turn });
