+      verdicts.push({ scen: 'S2 phase', pass: edited && !psFileWrite, detail: `phases=[${phases.join('>') || 'none (signal removed)'}] edited=${edited} ran=${ran} powershell-file-write=${psFileWrite ? 'YES(BAD)' : 'no'}` });
