+		jack.deposit(srcNo, new Amount(500, 0));
+		jack.transferBatch(jack.findMyAccount(srcNo), Arrays.asList(aNo, bNo, aNo), new Amount(100, 0));
+		assertEquals(200.0, jack.findMyAccount(srcNo).getBalance().toDouble(), 0.001);
