+  await writeFile(path.join(dir, 'tests.js'), TESTS, 'utf8');
+  await writeFile(path.join(dir, 'notes.txt'), 'one two three four five\n', 'utf8');
+  await writeFile(path.join(dir, 'app.js'), APP, 'utf8');
+  await writeFile(path.join(dir, 'package.json'), JSON.stringify({ name: 'case-app', version: '4.2.0' }, null, 2), 'utf8');
